sys_script_include.script:
var XurrentHMACUtil = Class.create();
XurrentHMACUtil.prototype = {
    initialize: function() {},

    generateHMAC: function(secret, payload) {
        var gce = new GlideCertificateEncryption();
        return 'sha256=' + gce.generateMac(payload, 'HmacSHA256', secret);
    },

    verifyHMAC: function(secret, payload, incomingSignature) {
        var expected = this.generateHMAC(secret, payload);
        return expected === incomingSignature;
    },

    type: 'XurrentHMACUtil'
};
